// Corner - the hot-corner picture (a screen with a mark in its chosen corner), light and dark: the icon of the
// Full Mode window on the taskbar. Both are 128 px, trimmed to the mark and set in a square, and made by
// design\hot-corner-sunburst\hc_apply.py; do not edit the text by hand.
using System;
using System.IO;
using System.Windows.Media.Imaging;

namespace Corner
{
    static class HotIcon
    {
        static BitmapSource light, dark;

        public static BitmapSource Image(bool darkMode)
        {
            if (darkMode) { if (dark == null) dark = Decode(PngDark); return dark; }
            if (light == null) light = Decode(PngLight);
            return light;
        }

        static BitmapSource Decode(string[] png)
        {
            var d = new PngBitmapDecoder(new MemoryStream(Convert.FromBase64String(string.Concat(png))), BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
            var f = d.Frames[0]; f.Freeze();
            return f;
        }

        static readonly string[] PngLight =
        {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        };

        static readonly string[] PngDark =
        {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        };
    }

    partial class Shell
    {
        /// The Full Mode window's icon (what the taskbar shows): the hot-corner picture that stands out on the taskbar, the
        /// white one on a dark taskbar and the dark one on a light taskbar (TaskbarDark, TrayIcon.cs). Called when Full Mode
        /// opens and after every look at the mode (Logo.cs), which would otherwise put the logo there.
        void ApplyFullIcon()
        {
            if (!full) return;
            try { var want = HotIcon.Image(!TaskbarDark()); if (Icon != want) Icon = want; }
            catch (Exception ex) { Store.Log(ex); }
        }
    }
}
